files.content:
body {
  margin: auto;
  background-color: #1e1e1e;
}

.buttons {
  align-items: center;
  flex-wrap: wrap;
  display: flex;
  gap: 20px;
  width: 80%;
  height: 100vh;
  margin: auto;
}

.button {
  width: 100px;
  height: 100px;
  border: none;
  border-radius: 10px;
  font-size: 60px;
  background-color: #fff;
  cursor: pointer;
}

.button:hover {
  box-shadow: 0 0 10px #fff;
}
